import { Injectable } from '@angular/core';
import { DocumentTab } from '../../../userpanel/interfaces/individual.interface';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { PDFAnnotation, temporaryAnnots } from '../../../pdf/interfaces/pdf.interface';
import { presentCurrentDetail, presentIndividualDetail } from '../../interfaces/present.inidvidual.interface';
import { presentPosition } from '../../interfaces/present-action.interface';
